package com.ruoyi.paicli.service;

import com.ruoyi.paicli.domain.*;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

public class PcSessionService {
    private final PcStore store;private final PcAccess access;private final PcIdempotency idem;private final PcEvidence evidence;private com.ruoyi.system.service.ISysUserService users;
    public PcSessionService(PcStore s,PcAccess a,PcIdempotency i,PcEvidence e){store=s;access=a;idem=i;evidence=e;}
    public PcSessionService(PcStore s,PcAccess a,PcIdempotency i,PcEvidence e,com.ruoyi.system.service.ISysUserService u){this(s,a,i,e);users=u;}
    private String requester(long user){if(users==null)return String.valueOf(user);var account=users.selectUserById(user);return account==null?String.valueOf(user):account.getUserName();}
    public List<PcRecord> list(long workspace,long user){access.workspace(workspace,user,false);return store.mapper.list(PcTable.SESSION,workspace,user,null,"ACTIVE");}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> create(long user,String key,Map<String,Object> input){return idem.run("user:"+user+":session",key,input,()->detail(createRaw(user,input),user));}
    private PcRecord createRaw(long user,Map<String,Object> input){
        long workspace=PcJson.number(input,"workspaceId"),runnerId=PcJson.number(input,"runnerId"),modelId=PcJson.number(input,"modelId");access.workspace(workspace,user,true);
        PcRecord runner=store.require(PcTable.RUNNER,runnerId,false);if(!Objects.equals(runner.getWorkspaceId(),workspace)||runner.getState().equals("REVOKED"))throw PcException.deny("Runner不属于当前工作区");
        model(modelId,workspace,user,false);validateMode(PcJson.text(input,"mode"));
        String title=PcJson.text(input,"title");if(title.isBlank()||title.length()>128)throw PcException.invalid("会话标题应为1至128字");
        Map<String,Object> p=new LinkedHashMap<>(input);p.remove("version");p.remove("id");p.put("approvalMode",approvalMode(PcJson.text(input,"approvalMode")));p.put("estimatedTokens",0L);p.put("compressionCount",0);p.put("externalMemoryPaused",false);
        return store.insert(PcTable.SESSION,workspace,user,null,null,runnerId,"SESSION","ACTIVE",null,p);
    }
    public PcRecord model(long id,long workspace,long user,boolean images){
        PcRecord m=store.require(PcTable.MODEL_CONFIG,id,false);if(!Objects.equals(m.getWorkspaceId(),workspace)||!Boolean.TRUE.equals(store.data(m).get("enabled")))throw PcException.deny("模型未在当前工作区启用");
        if(images&&!Boolean.TRUE.equals(store.data(m).get("supportsImages")))throw new PcException(422,"PC_MODEL_CAPABILITY","文本模型不支持附件图片，请换模型或删除图片");return m;
    }
    public Map<String,Object> detail(long id,long user){return detail(access.resource(PcTable.SESSION,id,user,true,false),user);}
    private Map<String,Object> detail(PcRecord r,long user){
        Map<String,Object> v=metadata(r);Object selected=store.data(r).get("modelId");if(selected!=null&&!selected.toString().equals("0")){PcRecord model=store.require(PcTable.MODEL_CONFIG,Long.parseLong(selected.toString()),false);Map<String,Object> config=store.view(model);v.put("modelConfig",config);v.put("model",config.get("modelId"));v.put("contextWindow",config.getOrDefault("contextWindow",128000));if(config.get("providerId")!=null){PcRecord provider=store.require(PcTable.PROVIDER_CONFIG,Long.parseLong(config.get("providerId").toString()),false);v.put("provider",store.data(provider).get("provider"));v.put("providerConfig",store.view(provider));}}v.put("eventCursor",String.valueOf(r.getSequenceNumber()));Map<String,Object> messages=recentMessages(r,user);v.put("messages",messages.get("messages"));v.put("messagesCursor",messages.get("cursor"));v.put("messagesHasMore",messages.get("hasMore"));v.put("earlierMessagesAvailable",messages.get("hasMore"));v.put("messagesStartSequence",messages.get("startSequence"));v.put("endSequence",r.getSequenceNumber());
        long planEnd=store.mapper.sessionRecordEnd(PcTable.PLAN,r.getWorkspaceId(),r.getId());if(planEnd>0)v.put("plan",store.view(store.require(PcTable.PLAN,planEnd,false)));
        for(String section:List.of("approvals","toolCalls")){Map<String,Object> page=recentSection(r,section);v.put(section,page.get("entries"));v.put(section+"HasMore",page.get("hasMore"));v.put(section+"Cursor",page.get("cursor"));v.put(section+"EndId",page.get("endId"));}v.put("context",context(r.getId(),user));
        var tasks=store.mapper.list(PcTable.TASK,r.getWorkspaceId(),r.getOwnerId(),null,null).stream().filter(x->Objects.equals(x.getSessionId(),r.getId())&&Set.of("ENQUEUED","RUNNING","LEASED","WAITING_APPROVAL","CANCELLING","RECONCILE_REQUIRED").contains(x.getState())).toList();if(!tasks.isEmpty())v.put("activeTaskId",String.valueOf(tasks.get(0).getId()));return v;
    }
    public Map<String,Object> ledger(long id,long user,long after,Long fixedEnd,int limit,boolean raw){PcRecord session=access.resource(PcTable.SESSION,id,user,true,false);long end=fixedEnd==null?session.getSequenceNumber():fixedEnd;if(after<0||after>end||end>session.getSequenceNumber()||limit<1||limit>200)throw PcException.invalid("账本分页范围非法");List<Map<String,Object>> entries=new ArrayList<>();long bytes=0,cursor=after;boolean more=false;List<PcRecord> rows=store.mapper.messages(session.getWorkspaceId(),user,id,after,end,limit+1);for(PcRecord row:rows){Map<String,Object> value=ledgerEntry(row,session,raw);long size=store.json.write(value).getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(size>20L*1024*1024)throw new PcException(413,"PC_LEDGER_RECORD_TOO_LARGE","原账本单记录超过20MB");if(entries.size()>=limit||!entries.isEmpty()&&bytes+size>16L*1024*1024){more=true;break;}entries.add(value);bytes+=size;cursor=row.getSequenceNumber();}return Map.of("schemaVersion",1,"sessionId",String.valueOf(id),"entries",entries,"cursor",cursor,"endSequence",end,"hasMore",more,"rawPromptIncluded",raw);}
    private Map<String,Object> metadata(PcRecord session){Map<String,Object> value=store.view(session);for(String field:List.of("promptLayers","messages","approvals","context","diagnostics"))value.remove(field);return value;}
    public Map<String,Object> messages(long id,long user,long after,Long fixedEnd,int limit){PcRecord session=access.resource(PcTable.SESSION,id,user,true,false);Map<String,Object> original=ledger(id,user,after,fixedEnd,limit,false);List<Map<String,Object>> views=messageViews((List<?>)original.get("entries"),session,user);Map<String,Object> result=new LinkedHashMap<>(original);result.remove("entries");result.put("messages",views);return result;}
    private List<Map<String,Object>> messageViews(List<?> entries,PcRecord session,long user){List<Map<String,Object>> views=new ArrayList<>();for(Object item:entries){Map<?,?> entry=(Map<?,?>)item;if(entry.get("message") instanceof Map<?,?> data){Map<String,Object> message=new LinkedHashMap<>();data.forEach((k,v)->message.put(k.toString(),v));message.put("sequence",entry.get("sequence"));message.put("id",entry.get("messageRecordId"));message.put("createdAt",entry.get("recordCreatedAt"));if(message.get("attachments") instanceof List<?> ids)message.put("attachments",ids.stream().map(a->{Map<String,Object> attachment=store.view(access.resource(PcTable.ARTIFACT,Long.parseLong(String.valueOf(a)),user,true,false));if(!Objects.equals(session.getWorkspaceId(),attachment.get("workspaceId")==null?null:Long.parseLong(attachment.get("workspaceId").toString())))throw PcException.deny("附件不属于会话工作区");for(String field:List.of("storageKey","chunks","leaseId","fencingToken","uploadId","uploadedBytes"))attachment.remove(field);attachment.putIfAbsent("contentType",attachment.get("mimeType"));return attachment;}).toList());views.add(message);}else if(Boolean.TRUE.equals(entry.get("rawPromptRequired")))views.add(Map.of("role","system","sequence",entry.get("sequence"),"rawPromptRequired",true));}return views;}
    private Map<String,Object> recentMessages(PcRecord session,long user){List<Map<String,Object>> entries=new ArrayList<>();long bytes=0;boolean more=false;for(PcRecord row:store.mapper.recentMessages(session.getWorkspaceId(),session.getOwnerId(),session.getId(),session.getSequenceNumber(),201)){Map<String,Object> entry=ledgerEntry(row,session,false);long size=store.json.write(entry).getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(size>20L*1024*1024)throw new PcException(413,"PC_LEDGER_RECORD_TOO_LARGE","原账本单记录超过20MiB");if(entries.size()>=200||!entries.isEmpty()&&bytes+size>16L*1024*1024){more=true;break;}entries.add(entry);bytes+=size;}Collections.reverse(entries);long start=entries.isEmpty()?session.getSequenceNumber():PcJson.number(entries.get(0),"sequence");return Map.of("messages",messageViews(entries,session,user),"cursor",session.getSequenceNumber(),"startSequence",start,"hasMore",more);}
    private Map<String,Object> recentSection(PcRecord session,String section){PcTable table=section.equals("approvals")?PcTable.APPROVAL:PcTable.TOOL_CALL;List<Map<String,Object>> entries=new ArrayList<>();long bytes=0;boolean more=false;for(PcRecord row:store.mapper.recentSessionRecords(table,session.getWorkspaceId(),session.getId(),201)){Map<String,Object> value=store.view(row);value.remove("permitCipher");value.remove("permitHash");long size=store.json.write(value).getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(entries.size()>=200||bytes+size>4L*1024*1024){more=true;break;}entries.add(value);bytes+=size;}Collections.reverse(entries);long end=store.mapper.sessionRecordEnd(table,session.getWorkspaceId(),session.getId());return Map.of("entries",entries,"cursor",String.valueOf(end),"endId",String.valueOf(end),"hasMore",more);}
    public Map<String,Object> exportData(long id,long user,boolean raw){PcRecord session=access.resource(PcTable.SESSION,id,user,true,false);Map<String,Object> ledger=ledger(id,user,0,session.getSequenceNumber(),200,raw);Map<String,Object> result=new LinkedHashMap<>();result.put("schemaVersion",1);result.put("session",metadata(session));result.put("ledgerEntries",ledger.get("entries"));result.put("ledgerHasMore",ledger.get("hasMore"));result.put("ledgerCursor",ledger.get("cursor"));result.put("endSequence",ledger.get("endSequence"));result.put("rawPromptIncluded",raw);result.put("ledgerPageEndpoint","/paicli/v1/sessions/"+id+"/ledger");Map<String,Object> pages=new LinkedHashMap<>();for(String section:List.of("events","plans","summaries","artifacts","toolCalls","approvals")){Map<String,Object> page=exportSection(id,user,section,0,null,200,raw,4L*1024*1024);result.put(section,page.get("entries"));Map<String,Object> continuation=new LinkedHashMap<>(page);continuation.remove("entries");continuation.put("endpoint","/paicli/v1/sessions/"+id+"/export-sections/"+section);pages.put(section,continuation);}result.put("sections",pages);return result;}
    public Map<String,Object> exportSection(long id,long user,String section,long after,Long fixedEnd,int limit,boolean raw){return exportSection(id,user,section,after,fixedEnd,limit,raw,48L*1024*1024);}
    private Map<String,Object> exportSection(long id,long user,String section,long after,Long fixedEnd,int limit,boolean raw,long budget){PcRecord session=access.resource(PcTable.SESSION,id,user,true,false);PcTable table=switch(section){case "events"->PcTable.EVENT;case "plans"->PcTable.PLAN;case "summaries"->PcTable.CONTEXT_SUMMARY;case "artifacts"->PcTable.ARTIFACT;case "toolCalls"->PcTable.TOOL_CALL;case "approvals"->PcTable.APPROVAL;default->throw PcException.invalid("未知导出集合");};long latest=store.mapper.sessionRecordEnd(table,session.getWorkspaceId(),id),end=fixedEnd==null?latest:fixedEnd;if(after<0||end<after||end>latest||limit<1||limit>200)throw PcException.invalid("导出分页范围非法");List<Map<String,Object>> entries=new ArrayList<>();long bytes=0,cursor=after;boolean more=false;for(PcRecord row:store.mapper.sessionRecords(table,session.getWorkspaceId(),id,after,end,limit+1)){Map<String,Object> value=table==PcTable.EVENT?safeEvent(row,raw):store.view(row);if(table==PcTable.ARTIFACT){for(String field:List.of("storageKey","chunks","leaseId","fencingToken","uploadId","uploadedBytes"))value.remove(field);value.put("contentType",value.get("mimeType"));}if(table==PcTable.TOOL_CALL||table==PcTable.APPROVAL){value.remove("permitCipher");value.remove("permitHash");}if(table==PcTable.CONTEXT_SUMMARY&&!raw){value.remove("messages");value.remove("summary");}long size=store.json.write(value).getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(size>56L*1024*1024)throw new PcException(413,"PC_EXPORT_RECORD_TOO_LARGE","单条元数据超过56MiB，请读取对应完整产物");if(entries.size()>=limit||bytes+size>budget){if(entries.isEmpty()&&budget>=48L*1024*1024){entries.add(value);cursor=row.getId();}else more=true;break;}entries.add(value);bytes+=size;cursor=row.getId();}if(cursor<end)more=true;return Map.of("schemaVersion",1,"sessionId",String.valueOf(id),"section",section,"entries",entries,"cursor",String.valueOf(cursor),"endId",String.valueOf(end),"hasMore",more,"rawPromptIncluded",raw);}
    private Map<String,Object> safeEvent(PcRecord row,boolean raw){Map<String,Object> event=evidence.eventView(row);if(!raw)event.put("payload",scrubPrompts(event.get("payload")));return event;}
    private Object scrubPrompts(Object value){if(value instanceof Map<?,?> map){Map<String,Object> clean=new LinkedHashMap<>();boolean system="system".equals(map.get("role"));map.forEach((k,v)->{String key=k.toString();if(!Set.of("derivedMessages","promptLayers").contains(key)&&!(system&&Set.of("content","contentParts","reasoningContent","toolCalls").contains(key)))clean.put(key,scrubPrompts(v));});if(system)clean.put("rawPromptRequired",true);return clean;}if(value instanceof List<?> list)return list.stream().map(this::scrubPrompts).toList();return value;}
    private Map<String,Object> ledgerEntry(PcRecord row,PcRecord session,boolean raw){Map<String,Object> data=new LinkedHashMap<>(store.data(row));Map<String,Object> entry=data.get("_ledger") instanceof Map<?,?>?new LinkedHashMap<>(PcJson.object(data,"_ledger")):new LinkedHashMap<>();data.remove("_ledger");entry.putIfAbsent("schemaVersion",1);entry.put("sessionId",String.valueOf(session.getId()));if(entry.containsKey("sequence"))entry.put("sourceSequence",entry.get("sequence"));entry.put("sequence",row.getSequenceNumber());entry.put("messageRecordId",String.valueOf(row.getId()));entry.put("recordCreatedAt",row.getCreatedAt().toString());entry.putIfAbsent("timestamp",row.getCreatedAt().toEpochMilli());entry.putIfAbsent("event","user".equals(data.get("role"))?"USER_INPUT":"LEDGER_MESSAGE");entry.putIfAbsent("mode",store.data(session).getOrDefault("mode","REACT"));entry.putIfAbsent("actor","user".equals(data.get("role"))?String.valueOf(row.getOwnerId()):PcJson.text(data,"role"));entry.putIfAbsent("source",row.getRunnerId()==null?"CENTER_USER":"RUNNER");entry.putIfAbsent("metadata",Map.of());if(!raw&&"system".equals(data.get("role"))){entry.put("messageHash",row.getContentHash());entry.put("rawPromptRequired",true);entry.put("message",null);}else entry.put("message",row.getKind().equals("LEDGER_EVENT")?null:data);if(!raw&&entry.get("metadata") instanceof Map<?,?> m){Map<String,Object> metadata=new LinkedHashMap<>();m.forEach((k,v)->{if(!Set.of("derivedMessages","promptLayers","content").contains(k.toString()))metadata.put(k.toString(),v);});entry.put("metadata",metadata);}return entry;}
    public Map<String,Object> context(long id,long user){return context(id,user,false);}
    public Map<String,Object> context(long id,long user,boolean raw){
        PcRecord r=access.resource(PcTable.SESSION,id,user,true,false);Map<String,Object> p=store.data(r),v=new LinkedHashMap<>();v.put("sessionId",String.valueOf(id));v.put("version",r.getVersion());v.put("estimatedTokens",p.getOrDefault("estimatedTokens",0L));
        long modelId=PcJson.number(p,"modelId");v.put("contextWindow",modelId==0?0:store.data(store.require(PcTable.MODEL_CONFIG,modelId,false)).getOrDefault("contextWindow",128000));v.put("messages",store.mapper.messageCount(r.getWorkspaceId(),user,r.getId()));v.put("compressionCount",p.getOrDefault("compressionCount",0));v.put("externalMemoryPaused",p.getOrDefault("externalMemoryPaused",false));v.put("rawLedgerAvailable",true);
        for(String name:List.of("lastCompressionStatus","compressionReason","usage","promptLayers","diagnostics"))if(p.containsKey(name))v.put(name,p.get(name));v.putIfAbsent("promptLayers",List.of());if(!raw&&v.get("promptLayers") instanceof List<?> layers)v.put("promptLayers",layers.stream().map(layer->{if(!(layer instanceof Map<?,?> map))return Map.of();Map<String,Object> metadata=new LinkedHashMap<>();for(String key:List.of("name","source","hash","sha256","tokens","tokenCount","type","version"))if(map.containsKey(key))metadata.put(key,map.get(key));return metadata;}).toList());v.putIfAbsent("diagnostics",List.of());Map<String,Object> artifacts=exportSection(id,user,"artifacts",0,null,200,false,4L*1024*1024);v.put("artifacts",artifacts.get("entries"));v.put("artifactsHasMore",artifacts.get("hasMore"));v.put("artifactsCursor",artifacts.get("cursor"));v.put("artifactsEndId",artifacts.get("endId"));return v;
    }
    @Transactional("paicliTransactionManager")
    public Map<String,Object> turn(long sessionId,long user,String key,long version,Map<String,Object> input){return idem.run("user:"+user+":turn:"+sessionId,key,Map.of("input",input,"version",version),()->{
        PcRecord session=access.resource(PcTable.SESSION,sessionId,user,true,true);store.version(session,version);return submitRaw(session,user,input,"WEB");
    });}
    public Map<String,Object> submitWechat(PcRecord session,long user,Map<String,Object> input){return submitRaw(session,user,input,"WECHAT");}
    private Map<String,Object> submitRaw(PcRecord session,long user,Map<String,Object> input,String source){
        if(!session.getState().equals("ACTIVE")||session.getRunnerId()==null||PcJson.text(store.data(session),"modelId").equals("0"))throw new PcException(409,"PC_SESSION_READ_ONLY","历史或控制会话仅供查看，请新建绑定当前Runner和模型的会话");access.workspace(session.getWorkspaceId(),user,true);String text=PcJson.text(input,"text");if(text.isBlank()||text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw PcException.invalid("请输入1至65536字的任务内容");
        List<?> attachments=input.get("attachments") instanceof List<?> l?l:List.of();if(attachments.size()>10)throw PcException.invalid("每轮最多10个附件");
        for(Object id:attachments){PcRecord a=access.resource(PcTable.ARTIFACT,Long.parseLong(String.valueOf(id)),user,true,false);if(!Objects.equals(a.getWorkspaceId(),session.getWorkspaceId()))throw PcException.deny("附件归属不匹配");}
        Map<String,Object> sp=store.data(session);long model=input.containsKey("modelId")?PcJson.number(input,"modelId"):PcJson.number(sp,"modelId");model(model,session.getWorkspaceId(),user,!attachments.isEmpty());
        String mode=input.containsKey("mode")?PcJson.text(input,"mode"):PcJson.text(sp,"mode");validateMode(mode);
        if(store.mapper.list(PcTable.TASK,null,null,null,"ENQUEUED").size()>=100)throw new PcException(429,"PC_QUEUE_FULL","中心排队任务已达100个，请等待现有任务结束");
        if(store.mapper.activeTasks(null,null,user,null)>=2)throw new PcException(429,"PC_USER_CAPACITY","每用户最多2个活跃会话，请等待或取消已有任务");
        PcRecord runner=store.require(PcTable.RUNNER,session.getRunnerId(),false);if(!"ONLINE".equals(runner.getState()))throw new PcException(503,"PC_RUNNER_OFFLINE","Runner未联机，请先连接设备");
        PcRecord workspace=store.require(PcTable.WORKSPACE,session.getWorkspaceId(),false);Map<String,Object> p=new LinkedHashMap<>();p.put("input",text);p.put("text",text);p.put("attachments",attachments);p.put("mode",mode);p.put("modelId",String.valueOf(model));PcRecord fixedModel=store.require(PcTable.MODEL_CONFIG,model,false);p.put("modelVersion",fixedModel.getVersion());if(store.data(fixedModel).containsKey("providerId")){PcRecord provider=store.require(PcTable.PROVIDER_CONFIG,PcJson.number(store.data(fixedModel),"providerId"),false);p.put("providerVersion",store.data(provider).getOrDefault("configurationVersion",provider.getVersion()));}p.put("approvalMode",approvalMode(input.containsKey("approvalMode")?PcJson.text(input,"approvalMode"):PcJson.text(sp,"approvalMode")));p.put("source",source);p.put("title",text.substring(0,Math.min(text.length(),128)));p.put("policyVersion",store.data(workspace).get("policyVersion"));p.put("planVersion",0L);p.put("rootFingerprint",store.data(workspace).get("rootFingerprint"));p.put("requesterName",requester(user));
        PcRecord turn=store.insert(PcTable.TURN,session.getWorkspaceId(),user,session.getId(),session.getId(),session.getRunnerId(),"TURN","ENQUEUED",null,p);p.put("turnId",String.valueOf(turn.getId()));
        PcRecord task=store.insert(PcTable.TASK,session.getWorkspaceId(),user,turn.getId(),session.getId(),session.getRunnerId(),"CODING","ENQUEUED",null,p);
        PcRecord message=store.insert(PcTable.MESSAGE,session.getWorkspaceId(),user,session.getId(),session.getId(),null,"MESSAGE","APPENDED",null,Map.of("role","user","content",text,"attachments",attachments));message.setSequenceNumber(session.getSequenceNumber()+1);store.save(PcTable.MESSAGE,message,store.data(message));
        store.insert(PcTable.DISPATCH_OUTBOX,session.getWorkspaceId(),user,task.getId(),session.getId(),session.getRunnerId(),"DISPATCH","PENDING","task:"+task.getId(),Map.of("taskId",String.valueOf(task.getId()),"attempts",0));
        evidence.event(session,task.getId(),"task:"+task.getId()+":enqueued","TASK_ENQUEUED",Map.of("taskId",String.valueOf(task.getId())));evidence.audit(session.getWorkspaceId(),user,task.getId(),session.getId(),"TURN_SUBMIT","ACCEPTED",Map.of("inputHash",store.json.hash(input)));
        return Map.of("taskId",String.valueOf(task.getId()),"version",task.getVersion(),"eventCursor",String.valueOf(store.require(PcTable.SESSION,session.getId(),false).getSequenceNumber()));
    }
    @Transactional("paicliTransactionManager")
    public Map<String,Object> background(long user,String key,Map<String,Object> input){return idem.run("user:"+user+":background",key,input,()->{PcRecord session=createRaw(user,input);Map<String,Object> result=submitRaw(session,user,input,"BACKGROUND");return task(PcJson.number(result,"taskId"),user);});}
    public List<PcRecord> tasks(long workspace,long user,String state){access.workspace(workspace,user,false);return store.mapper.list(PcTable.TASK,workspace,user,null,state);}
    public Map<String,Object> task(long id,long user){
        PcRecord r=access.resource(PcTable.TASK,id,user,true,false);Map<String,Object> result=store.view(r);result.put("tools",store.mapper.list(PcTable.TOOL_CALL,r.getWorkspaceId(),user,id,null).stream().map(store::view).toList());result.put("approvals",store.mapper.list(PcTable.APPROVAL,r.getWorkspaceId(),null,id,null).stream().map(store::view).toList());result.put("artifacts",store.mapper.list(PcTable.ARTIFACT,r.getWorkspaceId(),user,id,null).stream().map(row->{Map<String,Object> value=store.view(row);value.remove("storageKey");value.remove("chunks");value.put("contentType",value.get("mimeType"));return value;}).toList());Map<String,Object> events=taskEvents(id,user,0,null,200);result.put("events",events.get("events"));result.put("eventsCursor",events.get("cursor"));result.put("eventsHasMore",events.get("hasMore"));result.put("endSequence",events.get("endSequence"));
        PcRecord lease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+id,false);if(lease!=null){result.put("attemptId",String.valueOf(lease.getId()));result.put("fencingToken",String.valueOf(lease.getFencingToken()));result.put("leaseExpiresAt",lease.getExpiresAt());}
        if(r.getState().equals("RECONCILE_REQUIRED"))result.put("recovery",Map.of("lastToolResult","请查看最后已确认工具回执","fileDiff","须由Runner重新核对文件哈希","unknownEffects",List.of("执行租约已失效，未确认副作用不可重放"),"allowedDecisions",List.of("CONFIRM_COMPLETED","CONFIRM_FAILED","CONFIRM_CANCELLED")));return result;
    }
    @Transactional("paicliTransactionManager")
    public Map<String,Object> cancel(long id,long user,long version,String key){return idem.run("user:"+user+":cancel:"+id,key,Map.of("version",version),()->{
        PcRecord r=access.resource(PcTable.TASK,id,user,true,true);store.version(r,version);if(terminal(r.getState()))return store.view(r);
        r.setState(r.getState().equals("ENQUEUED")?"CANCELLED":"CANCELLING");store.save(PcTable.TASK,r,store.data(r));evidence.event(store.require(PcTable.SESSION,r.getSessionId(),false),id,null,"TASK_"+r.getState(),Map.of("taskId",String.valueOf(id),"version",r.getVersion()));return store.view(r);
    });}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> reconcile(long id,long user,long version,String key,Map<String,Object> input){return idem.run("user:"+user+":reconcile:"+id,key,input,()->{
        PcRecord r=access.resource(PcTable.TASK,id,user,true,true);access.approve(r.getWorkspaceId(),user);store.version(r,version);if(!r.getState().equals("RECONCILE_REQUIRED"))throw PcException.conflict("仅待核对任务可人工恢复");
        String reason=PcJson.text(input,"evidence"),finger=PcJson.text(input,"currentFingerprint"),decision=PcJson.text(input,"decision");if(reason.isBlank()||reason.length()>8192||!finger.matches("[a-f0-9]{64}"))throw PcException.invalid("须提供核对证据和当前仓库指纹");
        String terminal=switch(decision){case "CONFIRM_COMPLETED"->"COMPLETED";case "CONFIRM_FAILED"->"FAILED";case "CONFIRM_CANCELLED"->"CANCELLED";default->throw PcException.invalid("不支持盲重放，仅可确认当前实际结果");};
        Map<String,Object> p=store.data(r);p.put("reconciliation",input);r.setState(terminal);store.save(PcTable.TASK,r,p);evidence.audit(r.getWorkspaceId(),user,id,r.getSessionId(),"TASK_RECONCILE",terminal,Map.of("evidenceHash",store.json.hash(input)));evidence.event(store.require(PcTable.SESSION,r.getSessionId(),false),id,null,"TASK_"+terminal,Map.of("taskId",String.valueOf(id)));return store.view(r);
    });}
    public Map<String,Object> events(long sessionId,long user,long cursor,int limit){PcRecord session=access.resource(PcTable.SESSION,sessionId,user,true,false);long min=store.mapper.minCursor(session.getWorkspaceId(),sessionId,store.clock.instant());if(cursor<0||cursor>session.getSequenceNumber())throw PcException.invalid("事件游标非法");if(cursor>0&&((min>0&&cursor<min-1)||(min==0&&cursor<session.getSequenceNumber())))throw new PcException(410,"PC_EVENT_CURSOR_EXPIRED","事件游标已过期，请重新取会话快照");if(limit<1||limit>500)throw PcException.invalid("事件批次应为1至500条");List<PcRecord> rows=store.mapper.events(session.getWorkspaceId(),sessionId,cursor,limit+1,store.clock.instant());boolean more=rows.size()>limit;if(more)rows=rows.subList(0,limit);long latest=rows.isEmpty()?cursor:rows.get(rows.size()-1).getSequenceNumber();boolean terminal=store.mapper.activeTasks(null,sessionId,null,null)==0&&store.mapper.list(PcTable.TASK,session.getWorkspaceId(),user,null,"ENQUEUED").stream().noneMatch(t->Objects.equals(t.getSessionId(),sessionId));return Map.of("events",rows.stream().map(r->safeEvent(r,false)).toList(),"cursor",String.valueOf(latest),"hasMore",more,"terminal",terminal);}
    public Map<String,Object> taskEvents(long taskId,long user,long after,Long fixedEnd,int limit){PcRecord task=access.resource(PcTable.TASK,taskId,user,true,false),session=store.require(PcTable.SESSION,task.getSessionId(),false);long end=fixedEnd==null?session.getSequenceNumber():fixedEnd;if(after<0||after>end||end>session.getSequenceNumber()||limit<1||limit>200)throw PcException.invalid("任务事件分页范围非法");List<Map<String,Object>> events=new ArrayList<>();long cursor=after,bytes=0;boolean more=false;for(PcRecord row:store.mapper.taskEvents(task.getWorkspaceId(),task.getSessionId(),taskId,after,end,limit+1)){Map<String,Object> value=safeEvent(row,false);long size=store.json.write(value).getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(events.size()>=limit||!events.isEmpty()&&bytes+size>16L*1024*1024){more=true;break;}events.add(value);cursor=row.getSequenceNumber();bytes+=size;}return Map.of("events",events,"cursor",String.valueOf(cursor),"endSequence",end,"hasMore",more,"terminal",terminal(task.getState()));}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> contextAction(long id,long user,long version,String key,String action){return idem.run("user:"+user+":context:"+id,key,Map.of("version",version,"action",action),()->{
        PcRecord session=access.resource(PcTable.SESSION,id,user,true,true);store.version(session,version);if(!session.getState().equals("ACTIVE"))throw new PcException(409,"PC_SESSION_READ_ONLY","历史会话不能修改上下文");if(store.mapper.activeTasks(null,id,null,null)>0)throw PcException.conflict("会话运行中不能修改上下文");Map<String,Object> p=store.data(session);
        switch(action){case "CLEAR"->{p.put("contextStartSequence",session.getSequenceNumber());p.put("estimatedTokens",0);p.put("lastCompressionStatus","CLEARED");}case "CLEAR_INPUT_HISTORY"->p.put("inputHistoryClearedAt",store.clock.instant().toString());case "COMPRESS"->{return control(user,session.getWorkspaceId(),session.getRunnerId(),id,"CONTEXT_COMPRESS",Map.of("sessionVersion",session.getVersion(),"ledgerEndSequence",session.getSequenceNumber(),"contextStartSequence",p.getOrDefault("contextStartSequence",0)));}default->throw PcException.invalid("未知上下文操作");}
        store.save(PcTable.SESSION,session,p);evidence.audit(session.getWorkspaceId(),user,null,id,"CONTEXT_"+action,"ACCEPTED",Map.of("version",session.getVersion()));return context(id,user);
    });}
    /** 手动非模型操作仍通过同一租约、策略和回执；不在admin执行任何代码。调用方须已有事务。 */
    public Map<String,Object> control(long user,long workspace,long runnerId,Long sessionId,String operation,Map<String,Object> arguments){if(sessionId!=null&&!store.require(PcTable.SESSION,sessionId,false).getState().equals("ACTIVE"))throw new PcException(409,"PC_SESSION_READ_ONLY","历史会话仅供查看，请新建当前绑定会话");
        access.workspace(workspace,user,true);if(operation.equals("INIT_PROJECT_MEMORY"))arguments=PcProjectRuleService.initArguments(store,workspace,arguments);PcRecord runner=store.require(PcTable.RUNNER,runnerId,false);if(!Objects.equals(runner.getWorkspaceId(),workspace)||!runner.getState().equals("ONLINE"))throw new PcException(503,"PC_RUNNER_OFFLINE","工作区没有指定的在线Runner");
        if(sessionId==null){PcRecord s=store.insert(PcTable.SESSION,workspace,user,null,null,runnerId,"CONTROL","ACTIVE",null,Map.of("title",operation,"mode","REACT","approvalMode","ASK","modelId","0"));sessionId=s.getId();}
        PcRecord w=store.require(PcTable.WORKSPACE,workspace,false);Map<String,Object> payload=new LinkedHashMap<>();payload.put("operation",operation);payload.put("arguments",arguments);payload.put("mode","CONTROL");payload.put("policyVersion",store.data(w).get("policyVersion"));payload.put("planVersion",0);payload.put("rootFingerprint",store.data(w).get("rootFingerprint"));payload.put("title",operation);payload.put("source","CONTROL");payload.put("requesterName",requester(user));if(sessionId!=null){Object model=store.data(store.require(PcTable.SESSION,sessionId,false)).get("modelId");if(model!=null&&!model.toString().equals("0")){payload.put("modelId",model);PcRecord selected=store.require(PcTable.MODEL_CONFIG,Long.parseLong(model.toString()),false);payload.put("modelVersion",selected.getVersion());if(store.data(selected).containsKey("providerId")){PcRecord provider=store.require(PcTable.PROVIDER_CONFIG,PcJson.number(store.data(selected),"providerId"),false);payload.put("providerVersion",store.data(provider).getOrDefault("configurationVersion",provider.getVersion()));}}}
        PcRecord task=store.insert(PcTable.TASK,workspace,user,null,sessionId,runnerId,"CONTROL","ENQUEUED",null,payload);store.insert(PcTable.DISPATCH_OUTBOX,workspace,user,task.getId(),sessionId,runnerId,"DISPATCH","PENDING","task:"+task.getId(),Map.of("taskId",String.valueOf(task.getId()),"attempts",0));return store.view(task);
    }
    public static boolean terminal(String state){return Set.of("COMPLETED","FAILED","CANCELLED").contains(state);}
    public static void validateMode(String mode){if(!Set.of("REACT","PLAN","TEAM").contains(mode))throw PcException.invalid("模式应为REACT、PLAN或TEAM");}
    private static String approvalMode(String mode){if(mode.isBlank())return "ASK";if(!Set.of("AUTO","ASK","PLAN").contains(mode))throw PcException.invalid("审批模式非法");return mode;}
}
